import collections,json,statistics
from pathlib import Path
ROOT=Path(__file__).resolve().parents[5];OUT=ROOT/'experiments/003/results/stage6';POL=['wait','reject','retry','drop']
def read(p):return json.loads(p.read_text())
def table(headers,rows):return '\n'.join(['|'+'|'.join(headers)+'|','|'+'|'.join(['---']*len(headers))+'|']+['|'+'|'.join(map(str,row))+'|' for row in rows])+'\n'
def mean(rows,key):return statistics.mean(r[key] for r in rows)
def span(values,scale=1,digits=2):
 values=[x for x in values if x is not None]
 return f'{min(values)/scale:.{digits}f}–{max(values)/scale:.{digits}f}' if values else 'undefined'
def effect(x,scale=1,digits=3):
 if x['mean'] is None:return 'incomplete/undefined'
 return f'{x["mean"]*scale:.{digits}f} [{x["interval95"][0]*scale:.{digits}f}, {x["interval95"][1]*scale:.{digits}f}]'
